Fixes: 915cc7ac0f8e ("RDMA/irdma: Add miscellaneous utility definitions")
Link: https://patch.msgid.link/r/20251127143150.121099-1-mschmidt@redhat.com
Signed-off-by: Michal Schmidt <mschmidt@redhat.com>
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>

Here is the root cause:
The function `irdma_net_event()` accesses `neigh->dev` (by casting `ptr` to `struct neighbour *` and reading `dev`) before verifying that the event is `NETEVENT_NEIGH_UPDATE`. For other events, `ptr` points to a different, potentially smaller structure, resulting in an out-of-bounds read and a KASAN stack-out-of-bounds error.

Here is the patch:
  */
 int irdma_net_event(struct notifier_block *notifier, unsigned long event,
 		    void *ptr)
 {
 	struct neighbour *neigh = ptr;
-	struct net_device *real_dev, *netdev = (struct net_device *)neigh->dev;
+	struct net_device *real_dev, *netdev;
 	struct irdma_device *iwdev;
 	struct ib_device *ibdev;
 	__be32 *p;
 	u32 local_ipaddr[4] = {};
 	bool ipv4 = true;

 	switch (event) {
 	case NETEVENT_NEIGH_UPDATE:
+		netdev = neigh->dev;
 		real_dev = rdma_vlan_dev_real_dev(netdev);
 		if (!real_dev)
 			real_dev = netdev;
 		ibdev = ib_device_get_by_netdev(real_dev, RDMA_DRIVER_IRDMA);
 		if (!ibdev)
 			return NOTIFY_DONE;

 		iwdev = to_iwdev(ibdev);
 		p = (__be32 *)neigh->primary_key;
 		if (neigh->tbl->family == AF_INET6) {
 			ipv4 = false;
 			irdma_copy_ip_ntohl(local_ipaddr, p);
 		} else {
 			local_ipaddr[0] = ntohl(*p);
 		}

 		ibdev_dbg(&iwdev->ibdev,
 			  "DEV: netdev %p state %d local_ip=%pI4 MAC=%pM\n",
 			  iwdev->netdev, neigh->nud_state, local_ipaddr,
 			  neigh->ha);

 		if (neigh->nud_state & NUD_VALID)
 			irdma_add_arp(iwdev->rf, local_ipaddr, ipv4, neigh->ha);

 		else
 			irdma_manage_arp_cache(iwdev->rf, neigh->ha,
 					       local_ipaddr, ipv4,
 					       IRDMA_ARP_DELETE);
 		ib_device_put(ibdev);
 		break;
 	default:
 		break;
 	}

 	return NOTIFY_DONE;
 }



